events.text:
usage: agent-comms invoke [-h] --tool TOOL [--arguments ARGUMENTS]

options:
  -h, --help            show this help message and exit
  --tool TOOL
  --arguments ARGUMENTS
                        Tool arguments as a JSON object
{
  "tools": [
    {
      "name": "comms_pin_channel",
      "label": "Pin Channel",
      "description": "Persist whether a channel is pinned. Pinned channels sort before unpinned channels; the selected channel sort remains the secondary order.",
      "parameters": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Channel name"
          },
          "pinned": {
            "type": "boolean",
            "description": "True to pin; false to unpin"
          }
        },
        "required": [
          "name",
          "pinned"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_pin_thread",
      "label": "Pin Thread in Channel",
      "description": "Persist whether a member is pinned within one channel. Pins do not change membership or ordering in other channels. The selected member sort remains the secondary order.",
      "parameters": {
        "type": "object",
        "properties": {
          "channel": {
            "type": "string",
            "description": "Channel containing the thread"
          },
          "name": {
            "type": "string",
            "description": "Member thread name"
          },
          "pinned": {
            "type": "boolean",
            "description": "True to pin; false to unpin"
          }
        },
        "required": [
          "channel",
          "name",
          "pinned"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_model",
      "label": "Change Thread Model",
      "description": "Change this thread's model, or another thread's model, for its future turns. Optionally change its thinking level too. Applies from that thread's next turn.",
      "parameters": {
        "type": "object",
        "properties": {
          "thread": {
            "type": "string",
            "description": "Thread to change (defaults to the executing thread)"
          },
          "model": {
            "type": "string",
            "description": "Provider/model identifier"
          },
          "thinking_level": {
            "type": "string",
            "description": "Optional Pi thinking level",
            "enum": [
              "off",
              "minimal",
              "low",
              "medium",
              "high",
              "xhigh",
              "max"
            ],
            "default": ""
          }
        },
        "required": [
          "model"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_sort_channels",
      "label": "Sort Channels",
      "description": "Persist channel-list ordering independently of member ordering. Pinned channels stay first, with built-in channels first within each pin group.",
      "parameters": {
        "type": "object",
        "properties": {
          "order": {
            "type": "string",
            "enum": [
              "name",
              "created_at",
              "last_activity",
              "last_user_input"
            ],
            "description": "Channel list order"
          }
        },
        "required": [
          "order"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_tags",
      "label": "Manage tags",
      "description": "List, create, rename, or delete tags. Renaming/deleting updates thread assignments and channel filters. Uncovered tags automatically have a channel.",
      "parameters": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "enum": [
              "list",
              "create",
              "rename",
              "delete"
            ],
            "description": "Operation",
            "default": "list"
          },
          "name": {
            "type": "string",
            "description": "Tag name",
            "default": ""
          },
          "new_name": {
            "type": "string",
            "description": "Replacement tag for rename",
            "default": ""
          }
        },
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_thread_tags",
      "label": "Assign thread tags",
      "description": "Add/remove tags on a thread. Omit thread to manage your own tags. Channel membership and routing update immediately without restarting or creating an executor.",
      "parameters": {
        "type": "object",
        "properties": {
          "thread": {
            "type": "string",
            "description": "Thread name or alias",
            "default": ""
          },
          "add": {
            "type": "string",
            "description": "Comma-separated tags to add",
            "default": ""
          },
          "remove": {
            "type": "string",
            "description": "Comma-separated tags to remove",
            "default": ""
          }
        },
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_channels",
      "label": "List channels",
      "description": "List named tag views and their current member threads; #any includes everyone.",
      "parameters": {
        "type": "object",
        "properties": {},
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_set_channel_metadata",
      "label": "Set channel presentation",
      "description": "Set presentation-only parent and archive state. These fields never alter routing, membership, history, unread state, or delivery.",
      "parameters": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Exact channel name"
          },
          "parent": {
            "type": "string",
            "description": "Parent channel; empty clears the parent"
          },
          "archived": {
            "type": "boolean",
            "description": "Whether to hide from active presentation"
          }
        },
        "required": [
          "name",
          "parent",
          "archived"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_set_view",
      "label": "Set non-routable view",
      "description": "Create/update a typed participant or activity projection. Views cannot receive messages and never own channel history.",
      "parameters": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "View name without #"
          },
          "kind": {
            "type": "string",
            "enum": [
              "participants",
              "activity"
            ],
            "description": "Projection kind"
          },
          "match": {
            "type": "string",
            "enum": [
              "any_of",
              "all_of"
            ],
            "description": "Tag predicate"
          },
          "tags": {
            "type": "string",
            "description": "One or more comma-separated tags"
          }
        },
        "required": [
          "name",
          "kind",
          "match",
          "tags"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_delete_view",
      "label": "Delete non-routable view",
      "description": "Delete a saved projection without changing tags, channels, messages, or threads.",
      "parameters": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Saved view name"
          }
        },
        "required": [
          "name"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_sort_channel",
      "label": "Sort channel members",
      "description": "Persist one channel's member ordering, shared by all attached views.",
      "parameters": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Channel name"
          },
          "order": {
            "type": "string",
            "enum": [
              "last_message_sent",
              "created_at",
              "last_activity"
            ],
            "description": "Member ordering"
          }
        },
        "required": [
          "name",
          "order"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_set_project",
      "label": "Change Project",
      "description": "Change your own persistent project directory and synchronize attached clients. Accepts an existing absolute path, ~ path, or path relative to your current project. Preserves this thread and its conversation. After changing, end your turn; the runtime automatically continues in the new project.",
      "parameters": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "New project directory"
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_set_goal",
      "label": "Set persistent goal",
      "description": "Set or replace your own persistent goal. Use this when the user asks you to start, set, or pursue a goal autonomously.",
      "parameters": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string",
            "description": "Persistent objective to pursue"
          }
        },
        "required": [
          "text"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_goal",
      "label": "Goal progress",
      "description": "Update goal progress; complete it or block it when user input is needed. Use standby with explicit wait_for thread names when waiting for delegated work. The goal remains active, but only a direct message from a named dependency or a user follow-up starts its next turn. Do not repeatedly announce waiting or return empty output. If existing dependency replies block standby, inspect comms_inbox with this goal_id and wait_for. Read standby_review.messages and copy only standby_review.reviewed_inputs into reviewed_inputs; this records your decision to wait for a later reply without replaying uncertain inputs.",
      "parameters": {
        "type": "object",
        "properties": {
          "goal_id": {
            "type": "string",
            "description": "Goal identity provided in the turn context"
          },
          "status": {
            "type": "string",
            "enum": [
              "active",
              "standby",
              "completed",
              "blocked"
            ],
            "description": "Goal state"
          },
          "progress": {
            "type": "string",
            "description": "Progress summary; blocked requires a nonempty explicit reason"
          },
          "wait_for": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Explicit thread names or @names; required for standby"
          },
          "reviewed_inputs": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Exact unresolved inputId keys inspected and handled for this goal; standby only"
          }
        },
        "required": [
          "goal_id",
          "status",
          "progress"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_resume_goal",
      "label": "Resume paused goal",
      "description": "Resume your own paused goal with the same ID only after an explicit user request. This does not replace the goal or resume blocked/completed goals.",
      "parameters": {
        "type": "object",
        "properties": {
          "goal_id": {
            "type": "string",
            "description": "Identity of the paused goal to resume"
          },
          "progress": {
            "type": "string",
            "description": "Progress summary for the resumed goal"
          }
        },
        "required": [
          "goal_id",
          "progress"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_edit_goal",
      "label": "Edit goal text",
      "description": "Edit your existing goal text while keeping its identity, status, and progress. Use comms_set_goal only to replace the objective with a fresh goal ID.",
      "parameters": {
        "type": "object",
        "properties": {
          "goal_id": {
            "type": "string",
            "description": "Identity of the existing goal to edit"
          },
          "text": {
            "type": "string",
            "description": "Revised objective text, including any @mentions"
          }
        },
        "required": [
          "goal_id",
          "text"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_goal_history",
      "label": "Goal history",
      "description": "Read recorded goal revisions and recorded provenance and observation gaps.",
      "parameters": {
        "type": "object",
        "properties": {
          "goal_id": {
            "type": "string",
            "description": "Optional goal ID; omit for this thread's full history",
            "default": ""
          }
        },
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_threads",
      "label": "Comms Threads",
      "description": "List agent threads on the coordination wire with status and pending counts.",
      "parameters": {
        "type": "object",
        "properties": {
          "active_only": {
            "type": "boolean",
            "description": "Exclude stopped threads",
            "default": false
          }
        },
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_collaboration",
      "label": "Manage mutual collaboration",
      "description": "Create, update or end one mutual contact with another agent. Either participant can add, change its shared note, or remove it from both collaboration lists. This persistent metadata does not message, wake or fork either agent.",
      "parameters": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "enum": [
              "add",
              "update",
              "remove"
            ],
            "description": "Relationship change"
          },
          "peer": {
            "type": "string",
            "description": "Collaborating agent thread name or alias"
          },
          "note": {
            "type": "string",
            "description": "Short description of ongoing work",
            "default": ""
          }
        },
        "required": [
          "action",
          "peer"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_collaborations",
      "label": "List collaborations",
      "description": "Read explicit contacts and goal-derived awareness with provenance, without changing delivery, work acceptance or owners.",
      "parameters": {
        "type": "object",
        "properties": {},
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_rename_self",
      "label": "Rename Comms Thread",
      "description": "Rename your own persistent thread identity; old names remain routing aliases.",
      "parameters": {
        "type": "object",
        "properties": {
          "new_name": {
            "type": "string",
            "description": "Your new thread name"
          }
        },
        "required": [
          "new_name"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_send",
      "label": "Comms Send",
      "description": "Send a message to another thread or channel. Address specific threads with @thread-name in the body: the named threads are told they are the intended readers, and others dismiss quietly. Unknown names stay plain text.",
      "parameters": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Sender thread name"
          },
          "to": {
            "type": "string",
            "description": "Target thread name or channel"
          },
          "body": {
            "type": "string",
            "description": "Message text"
          },
          "type": {
            "type": "string",
            "enum": [
              "info",
              "question",
              "ack",
              "handoff",
              "alert"
            ],
            "description": "Message type",
            "default": "info"
          }
        },
        "required": [
          "from",
          "to",
          "body"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_decision",
      "label": "Record Decision",
      "description": "Record a chosen alternative and valid rejected alternatives on its original wire message. Author and source turn come from your admitted execution. Defaults to current project/goal revision or current turn; corrections name the original reference and grant no execution.",
      "parameters": {
        "type": "object",
        "properties": {
          "to": {
            "type": "string",
            "description": "Thread or channel receiving the original declaration"
          },
          "scope": {
            "oneOf": [
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "current"
                  }
                },
                "required": [
                  "kind"
                ],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "explicit"
                  },
                  "scope": {
                    "oneOf": [
                      {
                        "type": "object",
                        "properties": {
                          "kind": {
                            "type": "string",
                            "const": "goal"
                          },
                          "project": {
                            "type": "string"
                          },
                          "goal": {
                            "type": "object",
                            "properties": {
                              "id": {
                                "type": "string"
                              },
                              "revision": {
                                "type": "integer"
                              }
                            },
                            "required": [
                              "id",
                              "revision"
                            ],
                            "additionalProperties": false
                          }
                        },
                        "required": [
                          "kind",
                          "project",
                          "goal"
                        ],
                        "additionalProperties": false
                      },
                      {
                        "type": "object",
                        "properties": {
                          "kind": {
                            "type": "string",
                            "const": "project"
                          },
                          "project": {
                            "type": "string"
                          }
                        },
                        "required": [
                          "kind",
                          "project"
                        ],
                        "additionalProperties": false
                      },
                      {
                        "type": "object",
                        "properties": {
                          "kind": {
                            "type": "string",
                            "const": "turn"
                          },
                          "project": {
                            "type": "string"
                          }
                        },
                        "required": [
                          "kind",
                          "project"
                        ],
                        "additionalProperties": false
                      }
                    ]
                  }
                },
                "required": [
                  "kind",
                  "scope"
                ],
                "additionalProperties": false
              }
            ],
            "description": "Current project/goal or explicit scope",
            "default": {
              "kind": "current"
            }
          },
          "change": {
            "oneOf": [
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "original"
                  }
                },
                "required": [
                  "kind"
                ],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "correction"
                  },
                  "original": {
                    "type": "object",
                    "properties": {
                      "seq": {
                        "type": "integer"
                      },
                      "message_id": {
                        "type": "string"
                      }
                    },
                    "required": [
                      "seq",
                      "message_id"
                    ],
                    "additionalProperties": false
                  }
                },
                "required": [
                  "kind",
                  "original"
                ],
                "additionalProperties": false
              }
            ],
            "description": "Original declaration or correction naming its original reference",
            "default": {
              "kind": "original"
            }
          },
          "chosen": {
            "type": "string",
            "description": "Chosen alternative, preserving exact wording"
          },
          "rejected": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Nonempty unique valid rejected alternatives"
          }
        },
        "required": [
          "to",
          "chosen",
          "rejected"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_constraint",
      "label": "Record Constraint",
      "description": "Declare an exact authored restriction on its original wire message; wording is retained verbatim. This records your admitted authorship, not inferred human authority. Defaults to current project/goal revision or current turn. Corrections name the original constraint reference; no execution or replay is authorized.",
      "parameters": {
        "type": "object",
        "properties": {
          "to": {
            "type": "string",
            "description": "Thread or channel receiving the original declaration"
          },
          "scope": {
            "oneOf": [
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "current"
                  }
                },
                "required": [
                  "kind"
                ],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "explicit"
                  },
                  "scope": {
                    "oneOf": [
                      {
                        "type": "object",
                        "properties": {
                          "kind": {
                            "type": "string",
                            "const": "goal"
                          },
                          "project": {
                            "type": "string"
                          },
                          "goal": {
                            "type": "object",
                            "properties": {
                              "id": {
                                "type": "string"
                              },
                              "revision": {
                                "type": "integer"
                              }
                            },
                            "required": [
                              "id",
                              "revision"
                            ],
                            "additionalProperties": false
                          }
                        },
                        "required": [
                          "kind",
                          "project",
                          "goal"
                        ],
                        "additionalProperties": false
                      },
                      {
                        "type": "object",
                        "properties": {
                          "kind": {
                            "type": "string",
                            "const": "project"
                          },
                          "project": {
                            "type": "string"
                          }
                        },
                        "required": [
                          "kind",
                          "project"
                        ],
                        "additionalProperties": false
                      },
                      {
                        "type": "object",
                        "properties": {
                          "kind": {
                            "type": "string",
                            "const": "turn"
                          },
                          "project": {
                            "type": "string"
                          }
                        },
                        "required": [
                          "kind",
                          "project"
                        ],
                        "additionalProperties": false
                      }
                    ]
                  }
                },
                "required": [
                  "kind",
                  "scope"
                ],
                "additionalProperties": false
              }
            ],
            "description": "Current project/goal or explicit scope",
            "default": {
              "kind": "current"
            }
          },
          "change": {
            "oneOf": [
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "original"
                  }
                },
                "required": [
                  "kind"
                ],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "correction"
                  },
                  "original": {
                    "type": "object",
                    "properties": {
                      "seq": {
                        "type": "integer"
                      },
                      "message_id": {
                        "type": "string"
                      }
                    },
                    "required": [
                      "seq",
                      "message_id"
                    ],
                    "additionalProperties": false
                  }
                },
                "required": [
                  "kind",
                  "original"
                ],
                "additionalProperties": false
              }
            ],
            "description": "Original declaration or correction naming its original reference",
            "default": {
              "kind": "original"
            }
          },
          "text": {
            "type": "string",
            "description": "Exact authored restriction, never a paraphrase of another source"
          }
        },
        "required": [
          "to",
          "text"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "comms_subtask",
      "label": "Record Subtask",
      "description": "Explicitly record whether a described subtask is completed or unfinished. This is not assistant-turn termination or goal completion. Original author, turn, scope and correction reference use the existing admitted task owner. A completed observation may permit optional compaction when enabled.",
      "parameters": {
        "type": "object",
        "properties": {
          "to": {
            "type": "string",
            "description": "Thread or channel receiving the original declaration"
          },
          "scope": {
            "oneOf": [
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "current"
                  }
                },
                "required": [
                  "kind"
                ],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "kind": {
                    "type": "string",
                    "const": "explicit"
                  },
                  "scope": {
                    "oneOf": [
                      {
                        "type": "object",
                        "properties": {
                          "kind": {
                            "type": "string",
                            "const": "goal"
                          },
                          "project": {
                            "type": "string"
                          },
                          "goal": {
                            "type": "object",
                            "properties": {
                              "id": {
                                "type": "string"
                              },
                              "revision": {
                                "type": "integer"
                              }
                            },
                            "required": [
                              "id",
                              "revision"
                            ],
                            "additionalProperties": false
                          }
                        },
                        "required": [
                          "kind",
                          "project",
                          "goal"
                        ],
                        "additionalProperties": false
                      },
                      {
                        "type": "object",
                        "properties": {
                          "kind": {
                            "type": "string",
